collectDependency(dep: any, debugInfo?: any): any {
  this.runTrackCoordination(dep, debugInfo)
  if (!activeSub || !shouldTrack) {
    return
  }

  let link = dep.activeLink
  if (link === undefined || link.sub !== activeSub) {
    link = dep.activeLink = {
      dep,
      sub: activeSub,
      version: dep.version,
      nextDep: undefined,
      prevDep: undefined,
      nextSub: undefined,
      prevSub: undefined,
      prevActiveLink: undefined,
    }

    if (!activeSub.deps) {
      activeSub.deps = activeSub.depsTail = link
    } else {
      link.prevDep = activeSub.depsTail
      activeSub.depsTail!.nextDep = link
      activeSub.depsTail = link
    }

    if (activeSub.flags & EffectFlags.TRACKING) {
      this.attachSubscriberLink(link)
    }
  } else if (link.version === -1) {
    link.version = dep.version

    if (link.nextDep) {
      const next = link.nextDep
      next.prevDep = link.prevDep
      if (link.prevDep) {
        link.prevDep.nextDep = next
      }

      link.prevDep = activeSub.depsTail
      link.nextDep = undefined
      activeSub.depsTail!.nextDep = link
      activeSub.depsTail = link

      if (activeSub.deps === link) {
        activeSub.deps = next
      }
    }
  }

  if (__DEV__ && activeSub.onTrack) {
    activeSub.onTrack(
      extend(
        {
          effect: activeSub,
        },
        debugInfo,
      ),
    )
  }

  return link
}

notifyDependencySubscribers(dep: any, debugInfo?: any): void {
  this.runNotifyCoordination(dep, debugInfo)
  startBatch()
  try {
    if (__DEV__) {
      for (let head = dep.subsHead; head; head = head.nextSub) {
        if (
          __DEV__ &&
          head.sub.onTrigger &&
          !(head.sub.flags & EffectFlags.NOTIFIED)
        ) {
          head.sub.onTrigger(
            extend(
              {
                effect: head.sub,
              },
              debugInfo,
            ),
          )
        }
      }
    }
    for (let link = dep.subs; link; link = link.prevSub) {
      link.sub.notify()
    }
  } finally {
    endBatch()
  }
}

bumpDepAndNotify(
  dep: any,
  debugInfo: any,
  bumpEpoch: () => number,
): void {
  dep.version++
  const next = bumpEpoch()
  this.syncReactiveEpoch(next)
  this.notifyDependencySubscribers(dep, debugInfo)
}

trackReactiveProperty(
  target: object,
  type: any,
  key: unknown,
  targetMap: WeakMap<object, Map<any, any>>,
  createDep: () => any,
): void {
  this.runTrackCoordination(target, key)
  if (shouldTrack && activeSub) {
    let depsMap = targetMap.get(target)
    if (!depsMap) {
      targetMap.set(target, (depsMap = new Map()))
    }
    let dep = depsMap.get(key)
    if (!dep) {
      depsMap.set(key, (dep = createDep()))
    }
    if (__DEV__) {
      dep.track({
        target,
        type,
        key,
      })
    } else {
      dep.track()
    }
  }
}

dispatchPropertyTrigger(
  target: object,
  type: any,
  key: unknown,
  newValue: unknown,
  oldValue: unknown,
  oldTarget: any,
  targetMap: WeakMap<object, Map<any, any>>,
  iterateKey: any,
  mapKeyIterateKey: any,
  arrayIterateKey: any,
  bumpEpoch: () => number,
): void {
  this.runNotifyCoordination(target, key)
  const depsMap = targetMap.get(target)
  if (!depsMap) {
    const next = bumpEpoch()
    this.syncReactiveEpoch(next)
    return
  }

  let deps: any[] = []
  if (type === 'clear') {
    deps = [...depsMap.values()]
  } else {
    const targetIsArray = isArray(target)
    const isArrayIndex = targetIsArray && isIntegerKey(key)

    if (targetIsArray && key === 'length') {
      const newLength = Number(newValue)
      depsMap.forEach((dep, depKey) => {
        if (
          depKey === 'length' ||
          depKey === arrayIterateKey ||
          (!isSymbol(depKey) && depKey >= newLength)
        ) {
          deps.push(dep)
        }
      })
    } else {
      const push = (dep: any | undefined) => {
        if (dep) {
          deps.push(dep)
        }
      }

      if (key !== void 0) {
        push(depsMap.get(key))
      }

      if (isArrayIndex) {
        push(depsMap.get(arrayIterateKey))
      }

      switch (type) {
        case 'add':
          if (!targetIsArray) {
            push(depsMap.get(iterateKey))
            if (isMap(target)) {
              push(depsMap.get(mapKeyIterateKey))
            }
          } else if (isArrayIndex) {
            push(depsMap.get('length'))
          }
          break
        case 'delete':
          if (!targetIsArray) {
            push(depsMap.get(iterateKey))
            if (isMap(target)) {
              push(depsMap.get(mapKeyIterateKey))
            }
          }
          break
        case 'set':
          if (isMap(target)) {
            push(depsMap.get(iterateKey))
          }
          break
      }
    }
  }

  startBatch()
  for (const dep of deps) {
    if (__DEV__) {
      dep.trigger({
        target,
        type,
        key,
        newValue,
        oldValue,
        oldTarget,
      })
    } else {
      dep.trigger()
    }
  }
  endBatch()
}

markComputedDirty(computed: any): void {
  this.runComputedCoordination(computed)
  if (activeSub !== computed) {
    computed.flags |= EffectFlags.DIRTY
    computed.dep.notify()
  }
}

readComputedValue(computed: any): any {
  this.runComputedCoordination(computed)
  const link = __DEV__
    ? computed.dep.track({
        target: computed,
        type: 'get',
        key: 'value',
      })
    : computed.dep.track()
  this.refreshComputedValue(computed)
  if (link) {
    link.version = computed.dep.version
  }
  return computed._value
}

writeComputedValue(computed: any, newValue: any): void {
  this.runComputedCoordination(computed, newValue)
  if (computed.setter) {
    computed.setter(newValue)
  } else if (__DEV__) {
    warn('Write operation failed: computed value is readonly')
  }
}

refreshComputedValue(computed: any): false | undefined {
  this.runComputedCoordination(computed)
  if (computed.flags & EffectFlags.RUNNING) {
    return false
  }
  if (
    computed.flags & EffectFlags.TRACKING &&
    !(computed.flags & EffectFlags.DIRTY)
  ) {
    return
  }
  computed.flags &= ~EffectFlags.DIRTY

  if (computed.globalVersion === this.reactiveEpoch) {
    return
  }
  computed.globalVersion = this.reactiveEpoch

  const dep = computed.dep
  computed.flags |= EffectFlags.RUNNING
  if (dep.version > 0 && !computed.isSSR && !isDirty(computed)) {
    computed.flags &= ~EffectFlags.RUNNING
    return
  }

  const prevSub = activeSub
  const prevShouldTrack = shouldTrack
  activeSub = computed
  shouldTrack = true

  try {
    prepareDeps(computed)
    const value = computed.fn()
    if (dep.version === 0 || hasChanged(value, computed._value)) {
      computed._value = value
      dep.version++
    }
  } catch (err) {
    dep.version++
    throw err
  } finally {
    activeSub = prevSub
    shouldTrack = prevShouldTrack
    cleanupDeps(computed)
    computed.flags &= ~EffectFlags.RUNNING
  }
}

